referenceSolutions.javascript:
export function addBinary(left        , right        )         {
  let i = left.length - 1, j = right.length - 1, carry = 0; const digits           = []; while (i >= 0 || j >= 0 || carry) { const sum = (i >= 0 ? Number(left[i--]) : 0) + (j >= 0 ? Number(right[j--]) : 0) + carry; digits.push(String(sum % 2)); carry = Math.floor(sum / 2); } return digits.reverse().join('').replace(/^0+(?=.)/, '');
}

